use vstd::prelude::*;

verus! {

spec fn element_wise_mod_seq(a: Seq<u32>, b: Seq<u32>) -> Seq<u32>
    recommends
        a.len() == b.len(),
        forall|i: int| 0 <= i < b.len() ==> b[i] != 0,
{
    Seq::new(a.len(), |i: int| a[i] % b[i])
}

fn element_wise_module(arr1: &Vec<u32>, arr2: &Vec<u32>) -> (out: Vec<u32>)
    requires
        arr1@.len() == arr2@.len(),
        forall|i: int| 0 <= i < arr2@.len() ==> arr2@[i] != 0,
    ensures
        out@ == element_wise_mod_seq(arr1@, arr2@),
{
    assert_eq!(arr1.len(), arr2.len(), "Input arrays must have the same length");
    assert!(arr2.iter().all(|&x| x != 0), "All divisors must be non-zero");

    arr1.iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a % b)
        .collect()
}

} // verus!

